"""Generate src/onshape_duet/features/hole_defaults.py from the captured hole featurespec.

Dev script: python scripts/gen_hole_defaults.py
"""
import gzip
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SPECS = ROOT / "tests" / "fixtures" / "feature_specs.json.gz"
OUT = ROOT / "src" / "onshape_duet" / "features" / "hole_defaults.py"

HEADER = ('# Generated by scripts/gen_hole_defaults.py from tests/fixtures/feature_specs.json.gz.\n'
          '# Do not edit; regenerate with: python scripts/gen_hole_defaults.py\n')


def _expression(pid: str, d: dict) -> str:
    if (d.get("expression") or "").strip():
        return d["expression"]
    value, units = d.get("value", 0.0), d.get("units", "")
    if units == "meter":
        return f"{value * 1000:g} mm"
    if units == "degree":
        return f"{value:g} deg"
    if units == "":
        return f"{value:g}"
    raise ValueError(f"{pid}: unsupported quantity unit {units!r}")


def convert_param(spec_param: dict) -> dict | None:
    """One spec parameter to the emitted default, or None when it has no default."""
    d = spec_param.get("defaultValue")
    if not d:
        return None
    pid = spec_param["parameterId"]
    kind = d["btType"].rsplit("-", 1)[0]
    if kind == "BTMParameterBoolean":
        return {"btType": "BTMParameterBoolean-144", "parameterId": pid, "value": d["value"]}
    if kind == "BTMParameterEnum":
        return {"btType": "BTMParameterEnum-145", "parameterId": pid, "enumName": d["enumName"],
                "namespace": d.get("namespace", ""), "value": d["value"]}
    if kind == "BTMParameterString":
        return {"btType": "BTMParameterString-149", "parameterId": pid, "value": d["value"]}
    if kind == "BTMParameterQueryList":
        return {"btType": "BTMParameterQueryList-148", "parameterId": pid, "queries": []}
    if kind == "BTMParameterLookupTablePath":
        return {"btType": "BTMParameterLookupTablePath-1419", "parameterId": pid,
                "namespace": "", "value": dict(d["value"])}
    if kind == "BTMParameterQuantity":
        return {"btType": "BTMParameterQuantity-147", "parameterId": pid,
                "expression": _expression(pid, d), "isInteger": bool(d.get("isInteger", False))}
    raise ValueError(f"{pid}: unsupported parameter kind {kind!r}")


def convert(spec: dict) -> tuple[list[dict], int]:
    out, skipped = [], 0
    for sp in spec["parameters"]:
        c = convert_param(sp)
        if c is None:
            skipped += 1
        else:
            out.append(c)
    return out, skipped


def render(defaults: list[dict]) -> str:
    body = "".join(f"    {d!r},\n" for d in defaults)
    return f"{HEADER}\nHOLE_DEFAULTS: tuple[dict, ...] = (\n{body})\n"


def load_hole_spec() -> dict:
    with gzip.open(SPECS, "rt") as fh:
        specs = json.loads(fh.read())
    return next(s for s in specs["kept"] if s.get("featureType") == "hole")


def main() -> int:
    try:
        defaults, skipped = convert(load_hole_spec())
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1
    OUT.write_text(render(defaults))
    print(f"emitted {len(defaults)} parameters, skipped {skipped} (no default)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
